-- 커리큘럼을 제작한 전문가(training/domain/Expert). 운영에서 직접 등록하며 커리큘럼 상세에 이름·직함·소개·사진을 내린다.
-- title은 "교수"·"훈련사" 같은 직함이라 enum 대신 문자열로 둔다
CREATE TABLE "experts" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(50) NOT NULL,
    "title" VARCHAR(50) NOT NULL,
    "description" TEXT NOT NULL,
    "image_url" VARCHAR(512) NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL
);

-- 커리큘럼 하나에 제작 전문가는 한 명이다. 기존 커리큘럼은 전문가가 없으므로 NULL을 허용하고 운영에서 채운다
ALTER TABLE "curriculums" ADD COLUMN "expert_id" BIGINT REFERENCES "experts" ("id");
